"""Explicit data references; never execute expressions generated by an LLM."""

from __future__ import annotations

from collections.abc import Mapping
from copy import deepcopy
from typing import Any

from ..schemas import BusinessInput, ToolResult, ValueReference


def json_pointer(document: Any, pointer: str) -> Any:
    if not pointer:
        return deepcopy(document)
    if not pointer.startswith("/"):
        raise ValueError(f"Invalid JSON pointer: {pointer!r}")
    value = document
    for raw in pointer[1:].split("/"):
        # Reject malformed RFC 6901 escape sequences.
        index = 0
        while index < len(raw):
            if raw[index] == "~":
                if index + 1 == len(raw) or raw[index + 1] not in "01":
                    raise ValueError(f"Invalid JSON pointer escape: {pointer!r}")
                index += 1
            index += 1
        key = raw.replace("~1", "/").replace("~0", "~")
        if isinstance(value, dict):
            value = value[key]
        elif isinstance(value, list) and key.isascii() and key.isdigit():
            if len(key) > 1 and key.startswith("0"):
                raise ValueError("Array indices cannot have leading zeros")
            value = value[int(key)]
        else:
            raise ValueError(f"Cannot resolve {pointer!r} at {key!r}")
    return deepcopy(value)


def resolve(
    reference: ValueReference,
    request: BusinessInput,
    results: Mapping[str, ToolResult],
) -> Any:
    if reference.source == "input":
        return json_pointer(request.model_dump(mode="json"), reference.pointer)
    assert reference.task_id is not None
    result = results[reference.task_id]
    if reference.unit is not None:
        actual = result.output_units.get(reference.pointer)
        if actual != reference.unit:
            raise ValueError(
                f"Unit mismatch at {reference.task_id}{reference.pointer}: "
                f"expected {reference.unit}, got {actual}"
            )
    return json_pointer(result.payload, reference.pointer)
